"""Small calculator used by the E2E fixture."""


def add(a, b):
    return a + b


def percent_change(a, b):
    """Percent change from a to b; raises ValueError when a is 0."""
    # fixed in round 2
    if a == 0:
        raise ValueError("percent_change is undefined for a == 0")
    return (b - a) / a * 100.0
